INSERT INTO "modulo" ("numero","titulo","icono") VALUES(2,'Fundamentos de Desarrollo Front-End','devices');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(3,'Fundamentos de Programacion en JavaScript','data-object');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(4,'Programacion Avanzada en JavaScript','bolt');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(5,'Fundamentos de Bases de Datos Relacionales','database');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(6,'Desarrollo de Aplicaciones Web Node Express','dns');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(7,'Acceso a Datos en Aplicaciones Node','layers');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(8,'Implementacion de API Backend Node Express','shield-lock');
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(1,2,'json_2026',1,'¿Qué limita estrictamente al Front-End en comparación con el Back-End en la arquitectura web?','El Front-End corre dentro del navegador, y el navegador no le da acceso al sistema de archivos del servidor: esa es una frontera de seguridad, no una limitación de las herramientas. Las otras tres describen cosas que el Front-End sí hace (estilos dinámicos) o que simplemente no son ciertas (ningún framework es obligatorio).',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(2,2,'json_2026',2,'¿Cuál es el rol fundamental del protocolo HTTP en la comunicación entre capas de desarrollo web?','HTTP es un protocolo sin estado: cada petición llega sin memoria de las anteriores, y por eso las sesiones hay que construirlas encima con cookies o tokens. Las otras tres atribuyen a HTTP trabajos que hacen CSS, el compilador o la base de datos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(3,2,'json_2026',3,'En una arquitectura Fullstack clásica, ¿qué componente intermedio separa la lógica Front y Back?','La API es el contrato entre las dos capas: el Front-End pide y recibe datos sin saber cómo están guardados, y el Back-End los entrega sin saber cómo se van a dibujar. Esa separación es lo que permite cambiar un lado sin tocar el otro.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(4,2,'json_2026',4,'¿Para qué usaría primariamente el inspector del navegador un desarrollador Front-End al depurar?','El inspector sirve para las dos cosas a la vez: editar el DOM en vivo para probar un cambio sin recompilar, y mirar la pestaña de red para ver qué peticiones salieron y qué respondieron. Las otras tres describen tareas de servidor o de compilación, que no ocurren en el navegador.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(5,2,'json_2026',5,'Según la tríada de desarrollo web, ¿qué rol técnico fundamental asume JavaScript en cliente?','En la tríada, HTML pone la estructura, CSS la presentación y JavaScript el comportamiento: es el único de los tres que puede reaccionar a un evento y modificar el DOM después de que la página cargó. Las alternativas (a) y (b) describen justamente a HTML y a CSS.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(6,2,'json_2026',6,'En un formulario HTML5, ¿qué atributo del form define la URI destino al procesar datos enviados?','`action` es el atributo que dice a qué URI se envían los datos del formulario. `enctype` define cómo se codifican, `target` dónde se abre la respuesta, y `rel` ni siquiera pertenece a `<form>`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(7,2,'json_2026',7,'¿Cuál es la función semántica estricta de la etiqueta `<aside>` según los estándares de HTML5?','`<aside>` es para contenido relacionado con el principal pero que puede separarse de él sin que el texto pierda sentido: una barra lateral, una nota al margen, un bloque de enlaces relacionados. Si el contenido fuera indispensable para entender la página, no iría en un `<aside>`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(8,2,'json_2026',8,'¿Qué combinación de etiquetas HTML5 es correcta para instanciar un menú de opciones nativo?','El menú desplegable nativo de HTML es un `<select>` que contiene elementos `<option>`. Las otras tres combinan etiquetas que no existen en el estándar: `<dropdown>`, `<item>` y `<list>` son inventadas, y `<datalist>` existe pero acompaña a un `<input>`, no reemplaza al `<select>`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(9,2,'json_2026',9,'¿Dónde deben declararse semánticamente los links a hojas de estilos externas y metadatos vitales?','El `<head>` es donde va todo lo que describe el documento sin dibujarse: hojas de estilo, metadatos, título. Poner ahí la hoja de estilos permite además que el navegador empiece a pedirla antes de encontrarse con el contenido. La alternativa (b) es el error clásico de confundirla con los scripts, que sí se ponen al final del `<body>` y por un motivo distinto: no bloquear el dibujado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(10,2,'json_2026',10,'Para lograr accesibilidad, ¿qué etiqueta asocia lógicamente grupos de controles de formulario?','`<fieldset>` agrupa controles relacionados y, junto con `<legend>`, hace que un lector de pantalla anuncie a qué grupo pertenece cada campo. Las alternativas (a) y (c) son etiquetas inventadas, y (d) es un `<div>` con un rol ARIA: parcha la accesibilidad en vez de usar la etiqueta que ya existe para eso.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(11,2,'json_2026',11,'¿Qué atributo HTML asegura vincular explícita y unívocamente una etiqueta `<label>` con un input?','El atributo `for` del `<label>` apunta al `id` del campo, y ese vínculo hace dos cosas: el lector de pantalla anuncia la etiqueta al enfocar el campo, y hacer clic en el texto pone el cursor dentro. `name` sirve para enviar el dato, no para vincular.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(12,2,'json_2026',12,'En el modelo de cajas CSS, ¿qué propiedad añade espacio transparente externo perimetral al borde?','En el modelo de cajas, de adentro hacia afuera van contenido, `padding`, `border` y `margin`. El `margin` es el espacio exterior al borde, y es transparente: separa la caja de sus vecinas. El `padding` es el espacio interior, entre el contenido y el borde.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(13,2,'json_2026',13,'Según el cálculo de especificidad CSS, ¿cuál de los siguientes selectores prevalece en conflicto?','La especificidad se cuenta por categorías, y un identificador pesa más que cualquier cantidad de clases o elementos. Sólo (c) tiene un `#id`, así que gana sin necesidad de contar el resto: (a) suma dos clases, (b) una clase y cuatro elementos, y (d) sólo elementos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(14,2,'json_2026',14,'¿Qué atajo media query CSS restringe la regla exclusivamente a Viewports de mínimo 1024px?','`min-width` significa «desde este ancho hacia arriba», así que la regla se aplica a viewports de 1024px o más. La (a) hace justo lo contrario con `max-width`, y las otras dos usan sintaxis que no existe.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(15,2,'json_2026',15,'¿Qué declaración box-sizing engloba el padding y el border en el cálculo del width total asignado?','Con `border-box`, el `width` que declaras es el ancho final de la caja: el `padding` y el `border` se descuentan hacia adentro en vez de sumarse. Con `content-box`, que es el valor por omisión, el `width` describe sólo el contenido y todo lo demás se suma encima.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(16,2,'json_2026',16,'Ante la colisión de estilos de distintos orígenes, y sin usar `!important`, ¿qué estilo CSS impone mayor prioridad?','En la cascada, un estilo puesto en el atributo `style` del elemento pesa más que cualquier regla de una hoja de estilos, venga de un archivo externo o de un `<style>` embebido. La alternativa (d) es el distractor que más enseña: el orden de los orígenes es navegador, luego usuario, luego autor, así que la hoja del usuario queda por debajo. Sólo se invierte con `!important`, y por eso el enunciado lo descarta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(17,2,'json_2026',17,'¿Qué operador relacional CSS filtra afectando solo a los descendientes de primer grado (hijos)?','El signo `>` es el combinador de hijo directo: `div > p` afecta a los párrafos que cuelgan inmediatamente del `div`, no a los que están más abajo. El espacio alcanza a todos los descendientes, `+` al hermano inmediato y `~` a los hermanos siguientes.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(18,2,'json_2026',18,'¿Cuántas fracciones equitativas articulan como límite la arquitectura del grid de Bootstrap?','La grilla de Bootstrap divide cada fila en 12 columnas, y 12 se eligió porque se reparte en mitades, tercios, cuartos y sextos sin decimales. Por eso las clases van de `col-1` a `col-12` y la suma dentro de una fila debería dar 12.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(19,2,'json_2026',19,'¿Qué sufijo responsivo activa modificaciones de diseño en Bootstrap al superar el breakpoint grande?','El sufijo `lg` corresponde al breakpoint «grande», que en Bootstrap arranca en 992px. Los sufijos van de menor a mayor —`sm`, `md`, `lg`, `xl`— y cada uno aplica desde su ancho hacia arriba, no sólo dentro de un tramo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(20,2,'json_2026',20,'¿Qué clase central de Bootstrap estabiliza el margen limitando y centrando el ancho del contenido?','`.container` fija un ancho máximo por cada breakpoint y centra el bloque con márgenes automáticos. `.container-fluid` hace lo contrario: ocupa siempre el 100% del ancho disponible. Las otras dos clases no existen en Bootstrap.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(21,2,'json_2026',21,'En el sistema de utilidades, ¿qué clase induce a un nodo tipo block a ocupar el 100% de su padre?','`.w-100` es la utilidad de ancho que fija `width: 100%`, de modo que el elemento ocupa todo el ancho de su contenedor padre. Las otras tres no existen en Bootstrap.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(22,2,'json_2026',22,'En Bootstrap 4, ¿qué propósito de interfaz cumple el componente jumbotron?','El jumbotron es un bloque destacado, con fondo y espaciado generosos, para resaltar el mensaje principal al comienzo de una página. El enunciado dice «en Bootstrap 4» a propósito: en Bootstrap 5 el componente se eliminó y su efecto se reconstruye combinando utilidades de fondo, borde y espaciado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(23,2,'json_2026',23,'¿Bajo qué doctrina base se estructura algorítmicamente el flujo responsivo en Bootstrap por defecto?','Bootstrap está construido «mobile first»: los estilos base valen para pantallas chicas y las media queries usan `min-width` para ir agregando reglas hacia arriba. Por eso una clase sin sufijo, como `.col-6`, aplica desde el móvil en adelante.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(24,2,'json_2026',24,'En evaluación nativa de JavaScript, ¿qué método atrapa de forma veloz a un único nodo por su ID?','`getElementById()` va directo al índice interno de identificadores del documento, así que devuelve el nodo sin recorrer el árbol. `querySelector("[id]")` sí recorre y además devolvería el primer elemento que tenga cualquier `id`, no el que buscas; y `document.findAll()` no existe.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(25,2,'json_2026',25,'A nivel de memoria y asignación, ¿por qué es crítico utilizar "let" sobre "var" al iterar ciclos?','`var` se declara a nivel de función, así que en un bucle todas las vueltas comparten la misma variable, y una función definida dentro del ciclo termina viendo el último valor. `let` crea una variable nueva por cada iteración del bloque, y cada cierre captura la suya.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(26,2,'json_2026',26,'¿Qué detonante de evento del DOM percibe mutaciones confirmadas cuando el elemento pierde el foco?','`change` se dispara cuando el campo pierde el foco **y además** su valor cambió respecto de cuando lo ganó: por eso el enunciado dice «mutaciones confirmadas». `input` se dispara con cada tecla, sin esperar a que el campo se abandone.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(27,2,'json_2026',27,'Considerando la sintaxis funcional ES6, ¿qué sentencia declara una arrow function correctamente?','La sintaxis de una arrow function es lista de parámetros, flecha y cuerpo: `() => {}`. La (a) mezcla `function` con la flecha, que no se combinan; las otras dos no son sintaxis válida.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(28,2,'json_2026',28,'Si intentas reasignar una variable declarada con `const`, ¿qué ocurre en tiempo de ejecución?','Reasignar una variable declarada con `const` lanza un `TypeError` y corta la ejecución: el enlace entre el nombre y su valor es lo que `const` congela. Conviene no confundirlo con lo otro: si la constante apunta a un objeto o a un arreglo, **modificar su contenido está permitido** y no lanza nada. `const` protege la referencia, no lo referenciado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(29,2,'json_2026',29,'Durante la fase de coerción implícita, ¿qué entrega la ejecución de la sentencia binaria "3" + 3?','Con el operador `+`, si uno de los operandos es una cadena, JavaScript convierte el otro a cadena y concatena: `"3" + 3` da `"33"`, del tipo String. Es el `+` el que se comporta así; con `-`, `*` o `/` la conversión va hacia número y `"3" - 3` daría `0`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(30,2,'json_2026',30,'Al cargar jQuery, ¿qué símbolo queda definido como atajo de la función `jQuery`?','jQuery define la variable global `$` como atajo de la función `jQuery`, y por eso todo el código de la librería empieza con ese símbolo. Son la misma función con dos nombres: `$("#x")` y `jQuery("#x")` hacen lo mismo. Y como `$` es una variable corriente, se puede soltar con `jQuery.noConflict()` cuando otra librería la reclama.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(31,2,'json_2026',31,'¿Cuál es el patrón estandarizado para adjuntar manejadores "click" en nodos asíncronos vía jQuery?','`.on("click", ...)` es la forma vigente de asociar manejadores en jQuery, y es la que además permite delegar en un ancestro para que funcione con nodos que todavía no existen al momento de registrarla. `.bindClick()` y `.eventListener()` no existen, y la (b) dispara el clic en vez de escucharlo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(32,2,'json_2026',32,'¿Qué directriz bloquea la ejecución de scripts en jQuery hasta asegurar que el árbol DOM está listo?','`$(document).ready()` retrasa la ejecución hasta que el árbol DOM está construido, de modo que los selectores encuentren los elementos. Sin eso, un script en el `<head>` correría antes de que existieran los nodos que busca. Las otras tres no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(33,2,'json_2026',33,'Al parsear datos, ¿qué función encapsula jQuery para forzar la lectura del contenido de un `<input>`?','`.val()` lee y escribe el valor de los controles de formulario, que es donde vive el contenido de un `<input>`. `.text()` y `.html()` trabajan sobre el contenido entre etiquetas de apertura y cierre, y un `<input>` no tiene: es un elemento vacío.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(34,2,'json_2026',34,'¿Qué técnica animada nativa de jQuery altera gradualmente la opacidad hasta colapsar el nodo visual?','`.fadeOut()` baja la opacidad de forma gradual y, al terminar, oculta el elemento. `.hide()` lo esconde de golpe, `.slideUp()` lo colapsa por altura en vez de por opacidad, y `.collapse()` no es de jQuery sino de Bootstrap.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(35,2,'json_2026',35,'¿Qué mutación estructural consolida temporalmente ''git add'' en la topología de un flujo versionado?','`git add` mueve los cambios del directorio de trabajo al área de preparación, que es una zona intermedia donde se arma el próximo commit. No guarda nada en la historia todavía: eso lo hace `git commit`, que es la alternativa (b).',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(36,2,'json_2026',36,'Al gatillar ''git commit'' careciendo de archivos indexados previos, ¿qué respuesta retorna Git CLI?','Sin nada en el área de preparación no hay cambios que registrar, así que Git aborta e informa que no hay nada que confirmar. No inventa un commit vacío ni guarda el directorio de trabajo por su cuenta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(37,2,'json_2026',37,'Frente a múltiples vectores de desarrollo, ¿qué previene tácticamente el aislamiento en ramas (branch)?','Una rama aísla el trabajo en curso, de modo que el código a medio hacer no se mezcla con la línea principal hasta que alguien lo revise e integre. Las otras tres describen problemas de disco, de red o de criptografía, que no son lo que las ramas resuelven.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(38,2,'json_2026',39,'En presencia de un Merge Conflict grave, ¿qué protocolo manual asume irrevocablemente el usuario?','Ante un conflicto, Git marca las zonas en disputa dentro del archivo y se detiene: es la persona quien decide qué código queda y luego confirma la resolución con un commit. Las otras tres son maniobras para esquivar el conflicto, y todas pierden trabajo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(39,2,'json_2026',40,'¿Cuál es la disparidad motriz exacta entre invocar "git fetch" frente a procesar un "git pull"?','`git fetch` trae los commits del remoto y actualiza las ramas de seguimiento, sin tocar tu rama de trabajo: puedes mirar qué llegó antes de integrarlo. `git pull` hace ese mismo `fetch` y además lo fusiona en tu rama en el mismo acto.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(40,2,'js_2026',1,'¿Cuál es la principal responsabilidad arquitectónica del rol Front-End en una aplicación web moderna?','El rol Front-End se ocupa de lo que ocurre en el navegador: construir la interfaz y responder a lo que hace la persona. La lógica de negocio, la base de datos y la configuración del servidor pertenecen al Back-End o a operaciones.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(41,2,'js_2026',2,'¿Cuál selector CSS posee mayor especificidad entre un ID, una clase, un elemento y un pseudo-elemento?','En el cálculo de especificidad, los identificadores forman una categoría que pesa más que las clases, y las clases más que los elementos y pseudo-elementos. Un solo `#id` le gana a cualquier cantidad de clases.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(42,2,'js_2026',3,'¿Qué regla CSS se utiliza para aplicar estilos condicionales basados en el ancho de la pantalla?','`@media` es la regla que condiciona estilos a las características del dispositivo, y `max-width: 768px` los aplica desde ese ancho hacia abajo. Las otras tres son sintaxis inventada: no existen `@responsive`, `@viewport` con esa forma ni `@screen`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(43,2,'js_2026',4,'En el sistema de grillas de Bootstrap, ¿en cuántas columnas iguales se divide por defecto una fila?','Bootstrap divide cada fila en 12 columnas, número elegido por ser divisible en mitades, tercios, cuartos y sextos sin decimales.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(44,2,'js_2026',5,'¿Qué método nativo de JavaScript retorna el primer elemento que coincida con un selector CSS específico?','`querySelector()` acepta cualquier selector CSS y devuelve el primer elemento que coincida, o `null` si no hay ninguno. `querySelectorAll()` devuelve todos, y los dos `getElement...` sólo buscan por id o por clase, sin admitir selectores compuestos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(45,2,'js_2026',6,'¿Qué evento de JavaScript se dispara inmediatamente cuando un elemento HTML pierde el foco?','`blur` se dispara en cuanto el elemento pierde el foco, haya cambiado su valor o no. Es lo que lo separa de `change`, que además exige que el valor sea distinto del que tenía al recibir el foco.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(46,2,'js_2026',7,'¿Cuál es el ámbito (scope) de una variable declarada con la palabra clave let dentro de un bloque?','`let` tiene alcance de bloque: existe sólo entre las llaves donde se declaró, incluidas las de un `if` o un `for`. Es lo que la separa de `var`, que tiene alcance de función y se filtra fuera del bloque.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(47,2,'js_2026',8,'En jQuery, ¿qué método se utiliza para cambiar o extraer el contenido HTML interno de un elemento?','`.html()` lee o reemplaza el contenido HTML interno del elemento, interpretando las etiquetas. `.text()` hace lo mismo pero tratando todo como texto plano, y `.val()` trabaja sobre el valor de los controles de formulario.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(48,2,'js_2026',9,'¿Cómo se asocia un evento de clic a un botón utilizando la sintaxis estándar de la librería jQuery?','`$("button").click(function() { })` es el atajo de jQuery para registrar un manejador de clic. La (b) es JavaScript nativo y además está incompleta, y las otras dos usan métodos que jQuery no tiene.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(49,2,'js_2026',10,'¿Qué comando de Git registra oficialmente los cambios preparados (staging) en el repositorio local?','`git commit` toma lo que está en el área de preparación y lo registra en la historia del repositorio local. `git add` sólo prepara, `git push` envía al remoto lo ya confirmado, y `git status` no escribe nada.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(50,2,'js_2026',11,'¿Qué comando de Git permite crear una nueva rama y cambiar a ella de manera simultánea?','Los dos comandos crean la rama y se cambian a ella en un solo paso: `git checkout -b` es la forma clásica y `git switch --create` la moderna, que Git introdujo justamente para separar el cambio de rama de la restauración de archivos. Por eso la respuesta correcta es la que las reconoce a ambas, y por eso esta pregunta no se puede barajar: su alternativa (d) nombra a las otras dos por su letra.',NULL,1,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(51,2,'js_2026',12,'En GitHub, ¿qué propósito principal cumple la creación de un Pull Request (PR)?','Un Pull Request propone integrar una rama en otra y abre el espacio donde se revisa y comenta el cambio antes de fusionarlo. Es una función de la plataforma, no de Git: sirve para que la integración pase por una revisión.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(52,2,'js_2026',13,'¿Qué sucede cuando Git detecta modificaciones concurrentes en la misma línea durante una unión?','Cuando dos ramas modifican la misma línea, Git no puede decidir cuál gana: marca el conflicto dentro del archivo y detiene la fusión hasta que alguien lo resuelva a mano. No sobrescribe ni descarta nada por su cuenta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(53,3,'json_2026',1,'¿Cuál es el motor principal que compila y ejecuta JavaScript dentro de Google Chrome?','V8 es el motor de JavaScript de Chrome, y también el que hace funcionar a Node.js. Las otras tres existen de verdad y por eso son buenos distractores: SpiderMonkey es el de Firefox, JavaScriptCore el de Safari, y ChakraCore el del Edge antiguo, el que había antes de que Edge pasara a construirse sobre Chromium y adoptara V8.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(54,3,'json_2026',2,'¿Qué limitación de seguridad crítica tiene JavaScript al ejecutarse nativamente en el navegador?','El navegador ejecuta el código dentro de una caja de arena, y esa caja no le da acceso al sistema de archivos del equipo. Es una frontera de seguridad deliberada, no una carencia del lenguaje. Las otras tres describen cosas que JavaScript sí hace todos los días: modificar el DOM, pedir datos con `fetch` y animar. Ojo con un matiz que conviene entender: sí se pueden leer archivos que el usuario elige a mano en un `<input type="file">`, porque ahí el permiso lo da una persona. Lo prohibido es entrar solo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(55,3,'json_2026',3,'¿Para qué se utiliza principalmente la consola de comandos de JavaScript en el navegador?','La consola sirve para mirar por dentro un programa que ya está corriendo: escribir expresiones y ver qué devuelven, leer los errores, inspeccionar valores. Las otras tres describen herramientas distintas: JavaScript no se compila a ensamblador a mano, la interfaz se diseña con HTML y CSS, y la conexión a la base de datos vive en el servidor y no en el navegador.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(56,3,'json_2026',4,'En un entorno de navegador, ¿qué objeto global actúa como el contexto raíz de ejecución?','En el navegador, `window` es el objeto global: todo lo que se declara sin encerrar en un módulo o una función cuelga de ahí. `document` también es global, pero representa el documento y no el contexto raíz; `global` es el nombre que usa Node.js, no el navegador; y `navigator` describe el navegador y sus capacidades. Desde ES2020 existe además `globalThis`, que nombra el objeto global sea cual sea el entorno.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(57,3,'json_2026',5,'Al cargar un script en HTML, ¿qué atributo asegura que se ejecute tras parsear el documento?','`defer` le dice al navegador que descargue el script en paralelo pero que no lo ejecute hasta terminar de parsear el documento, y por eso el DOM ya está completo cuando el código corre. `async` también descarga en paralelo, pero ejecuta apenas termina la descarga, que puede ser en mitad del parseo; ese es justamente el par que hay que saber distinguir. `load` y `wait` no son atributos de `<script>`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(58,3,'json_2026',6,'¿Qué ocurre si un script con errores sintácticos severos se ejecuta en el navegador?','Un error de sintaxis se detecta al parsear, antes de ejecutar nada, así que ese script no llega a correr ni una sola línea y el motor informa un `SyntaxError` en la consola. Conviene precisar el alcance de esa detención: lo que no se ejecuta es **ese** script, mientras la página, los demás scripts y los manejadores de eventos siguen funcionando con normalidad. Ninguna de las otras tres ocurre: el navegador no corrige código, no recarga la página solo, y no puede saltarse la línea defectuosa porque no llegó a entender el archivo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(59,3,'json_2026',7,'¿Cuál es el principal beneficio de aislar el código JavaScript en un archivo externo .js?','Un archivo `.js` aparte lo pueden compartir varias páginas y el navegador lo guarda en caché, así que se descarga una vez y se reutiliza. Las otras tres prometen algo que no ocurre: separar el archivo no encripta nada, no obliga al servidor a procesarlo, y desde luego no impide descargarlo — cualquiera puede abrir la URL del archivo y leerlo entero.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(60,3,'json_2026',8,'Según las herramientas del browser, ¿qué pestaña permite analizar el rendimiento del script?','La pestaña «Performance» graba una línea de tiempo de lo que hizo la página: cuánto tardó cada función, dónde se fue el tiempo, qué bloqueó el dibujado. Las otras tres son pestañas reales con otro oficio: «Elements» inspecciona el DOM y los estilos, «Network» mira las peticiones y sus tiempos de red, y «Application» muestra almacenamiento, cookies y service workers.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(61,3,'json_2026',9,'¿Qué provoca declarar una variable sin usar let, const o var en modo no estricto?','En modo no estricto, asignar a un nombre que nunca se declaró crea una propiedad en el objeto global en vez de fallar. Es una de las razones de ser de `''use strict''`, que convierte ese descuido en un `ReferenceError`. Por eso la (a) no es correcta aquí: sí hay error, pero solo en modo estricto, que es justo lo que el enunciado descarta. Y no es local ni queda en `undefined`: queda global y con el valor asignado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(62,3,'json_2026',10,'Al evaluar la expresión `[] == false`, ¿qué resultado y por qué se produce en JavaScript?','El resultado es `true`, y la cadena de conversiones es lo que hay que entender: `false` se convierte al número `0`, y el arreglo vacío se convierte primero a la cadena `""` y de ahí al número `0`; `0 == 0` da verdadero. Lo que conviene fijar es que `==` compara convirtiendo a **número**, no a booleano. De ahí sale algo que parece contradictorio y no lo es: `[] == false` da `true` y al mismo tiempo `[] ? ''sí'' : ''no''` da `''sí''`, porque como condición un arreglo vacío es verdadero. Son dos reglas distintas —la de `==` y la de los valores truthy— y aplicarlas cruzadas es el error más común con este operador.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(63,3,'json_2026',11,'¿Qué valor asume una variable declarada con `let` pero que carece de inicialización explícita?','Declarar sin asignar deja la variable en `undefined`, que es el valor que JavaScript usa para «existe pero todavía no tiene nada». `null` es distinto: significa «vacío a propósito» y hay que escribirlo. `NaN` aparece al fallar una operación numérica, y `0` habría que asignarlo. La distinción entre `undefined` y `null` es una de las que más se preguntan.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(64,3,'json_2026',12,'¿Qué operador lógico retorna el primer operando falso o el último verdadero si todos lo son?','`&&` va evaluando de izquierda a derecha y se detiene en el primer operando falso, devolviéndolo tal cual; si ninguno lo es, devuelve el último. Esa es la razón de que `&&` no devuelva siempre `true` o `false` sino uno de los operandos. `||` hace lo simétrico: primer verdadero o último. `!` niega y siempre da booleano, y `??` solo reacciona ante `null` y `undefined`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(65,3,'json_2026',13,'¿Cuál es la precedencia correcta, de mayor a menor, en los operadores aritméticos básicos?','Multiplicación y división se evalúan antes que suma y resta, igual que en aritmética, y los paréntesis siguen mandando sobre todo. Por eso `2 + 3 * 4` da 14 y no 20. La (a) y la (c) invierten el orden, y la (d) es lo que pasaría si no hubiera precedencia, que es exactamente lo que la precedencia existe para evitar.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(66,3,'json_2026',14,'Si `a = 5` y evaluamos `b = a++`, ¿cuál es el valor final de `b` y `a` respectivamente?','El `++` puesto **después** de la variable devuelve el valor viejo y luego incrementa: `b` se queda con 5 y `a` pasa a 6. Si estuviera puesto antes, `b = ++a`, los dos valdrían 6, que es la alternativa (a). Esa diferencia entre postfijo y prefijo es todo lo que la pregunta evalúa, y es de las que se responden mal por leer rápido.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(67,3,'json_2026',15,'En un condicional `if ("0")`, ¿el bloque interno se ejecuta o se omite?','El bloque se ejecuta. En un condicional el valor se convierte a booleano, y **toda cadena no vacía es verdadera**, incluida `"0"`: lo que decide es que tenga caracteres, no lo que digan. La única cadena falsa es la vacía, `""`. Es una trampa clásica, porque el número `0` sí es falso y `"0"` se le parece a la vista.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(68,3,'json_2026',16,'¿Qué diferencia clave existe entre los operadores relacionales == y === en JavaScript?','`==` convierte tipos antes de comparar, así que `"5" == 5` es verdadero; `===` compara tipo y valor sin convertir nada, y por eso `"5" === 5` es falso. La (a) dice exactamente lo contrario y por eso es el distractor que separa al que sabe. La recomendación práctica es usar `===` siempre, salvo que se quiera la conversión a propósito y se sepa por qué.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(69,3,'json_2026',17,'Si intentas asignar un valor a un índice fuera del límite actual de un arreglo, ¿qué sucede?','El arreglo se estira hasta ese índice y su `length` crece para incluirlo. No hay error: los arreglos de JavaScript no tienen un tamaño reservado que pueda desbordarse. Las posiciones intermedias que quedaron sin valor se leen como `undefined`. Las otras tres suponen comportamientos que no existen: ni se lanza un `RangeError`, ni se ignora la asignación, ni se desplazan los índices ya ocupados.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(70,3,'json_2026',18,'¿Cómo afecta la modificación de un arreglo a sus referencias asignadas a otras variables?','Un arreglo es un objeto y las variables guardan una referencia a él, no una copia. Si dos variables apuntan al mismo arreglo, el cambio hecho a través de una se ve por la otra, porque hay un solo arreglo. Para obtener una copia hay que pedirla: `[...arr]` o `arr.slice()`, y aun así es una copia superficial. Es la causa de una parte grande de los errores con datos compartidos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(71,3,'json_2026',19,'¿Cuál es el propósito principal de la sentencia `continue` dentro de un ciclo `for`?','`continue` abandona la iteración en curso y salta a la siguiente, sin salir del ciclo. El que termina el bucle entero es `break`, que es la alternativa (a) y el par con el que siempre se confunde. `return` devuelve desde la función, no desde el ciclo, y no existe ninguna instrucción que reinicie el contador desde su valor inicial.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(72,3,'json_2026',20,'¿Qué diferencia conceptual rige entre un ciclo `while` y un bucle `do/while`?','`do/while` evalúa la condición **después** del bloque, así que el cuerpo corre al menos una vez aunque la condición sea falsa desde el principio; `while` la evalúa antes y puede no ejecutarse nunca. Esa es toda la diferencia, y es la que decide cuál usar: `do/while` sirve cuando hay que hacer algo primero y recién después preguntar si se repite.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(73,3,'json_2026',21,'En el contexto de arreglos asociativos simulados, ¿qué tipo subyacente de estructura son?','JavaScript no tiene arreglos asociativos de verdad: lo que se usa como tal son objetos, donde la clave de texto es el nombre de una propiedad. Por eso `obj["nombre"]` y `obj.nombre` son lo mismo. Los arreglos con índices numéricos son otra cosa y tienen `length` y métodos propios; matrices bidimensionales y tuplas inmutables no son estructuras nativas del lenguaje.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(74,3,'json_2026',22,'¿Por qué es una mala práctica declarar funciones internamente dentro de un bucle extenso?','Cada vuelta del ciclo crea una función nueva en memoria, aunque el código sea idéntico, y eso es trabajo y memoria sin motivo. La salida es declarar la función una vez fuera del bucle y llamarla dentro. No es un error de sintaxis ni rompe nada: el programa funciona, simplemente hace de más, y por eso es una mala práctica y no un fallo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(75,3,'json_2026',23,'¿Qué principio rige en las convenciones de "código limpio" (Clean Code) para nombrar variables?','El nombre tiene que decir qué guarda la variable o qué hace la función, de modo que el código se pueda leer sin ir a buscar la definición. `contadorDeIntentos` gana a `c` aunque sea más largo. Las otras tres proponen prácticas abandonadas o falsas: el largo de un nombre no consume memoria en tiempo de ejecución, la notación húngara cayó en desuso, y las mayúsculas se reservan por convención para constantes.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(76,3,'json_2026',24,'En un ciclo iterativo, ¿qué sucede si la condición de salida jamás se evalúa como falsa?','Si la condición nunca se vuelve falsa, el ciclo no termina: se queda girando y bloquea el hilo, que en el navegador significa una pestaña congelada. No hay ningún límite de iteraciones que lo detenga —la (a) inventa uno—, ni el compilador puede «optimizar» una condición que quizá sea correcta, ni el ciclo devuelve nada, porque nunca llega a salir.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(77,3,'json_2026',25,'¿Qué comportamiento describe la capacidad de alojar una función anónima dentro de una variable?','Que una función se pueda guardar en una variable, pasar como argumento y devolver desde otra función es lo que significa que las funciones sean ciudadanos de primera clase: valen lo mismo que cualquier otro dato. De ahí salen los callbacks y buena parte del estilo del lenguaje. Las otras tres nombran conceptos reales de JavaScript, pero ninguno describe lo que la pregunta plantea.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(78,3,'json_2026',26,'Si una función ejecuta un bloque de código pero omite la instrucción `return`, ¿qué devuelve?','Toda función devuelve algo, y si no se dice qué, devuelve `undefined`. No es un caso especial: es el valor por omisión del retorno. `null` habría que devolverlo a propósito, y `0` y `false` son valores concretos que nadie escribió. Conviene tenerlo claro porque `undefined` es lo que se recibe al usar el resultado de una función que en realidad no devolvía nada.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(79,3,'json_2026',27,'¿Qué sucede si pasas menos argumentos a una función de los definidos en sus parámetros?','Los parámetros que no reciben argumento quedan en `undefined`, y la función corre igual. JavaScript no comprueba la cantidad de argumentos: pasar de menos —o de más— no es un error. De ahí vienen los valores por omisión, `function f(x = 10)`, que existen justamente para no tener que comprobar a mano si llegó `undefined`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(80,3,'json_2026',28,'¿Por qué el uso excesivo de variables globales está catalogado como un antipatrón riesgoso?','Cualquier parte del programa puede leer y escribir una variable global, así que dos trozos de código que no se conocen pueden pisarse el valor, y encontrar quién lo hizo es difícil porque el sospechoso es todo el archivo. Las otras tres dicen cosas falsas: las globales no ocupan menos, admiten cualquier tipo de dato, y son accesibles desde dentro de ciclos y condicionales.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(81,3,'json_2026',29,'¿Qué regla determina el acceso a variables dentro de funciones anidadas (lexical scoping)?','El alcance léxico se decide por dónde está escrita la función, no por dónde se la llama: una función interna ve sus propias variables, las de la función que la contiene, y las globales. Ese encadenamiento hacia afuera es lo que hace posibles los closures. Las otras tres niegan justamente esa cadena, que es lo que la pregunta evalúa.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(82,3,'json_2026',30,'¿Qué efecto tiene declarar un parámetro con el mismo nombre que una variable global del scope?','Se llama shadowing: dentro de la función, el nombre se resuelve al parámetro y la variable global queda tapada mientras dure esa ejecución. No hay error ni conflicto —JavaScript permite repetir el nombre— y la global **no** se modifica: sigue intacta y vuelve a verse al salir de la función. Confundir «tapar» con «sobrescribir» es el error que la (c) recoge.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(83,3,'json_2026',31,'¿Qué palabra clave nativa y reservada da acceso dinámico a todos los parámetros en una función?','`arguments` es un objeto que existe dentro de toda función tradicional y contiene todos los argumentos recibidos, se hayan declarado como parámetros o no. `args`, `params` e `inputs` no son palabras del lenguaje. Conviene saber que `arguments` **no existe en las funciones flecha**, y que hoy se prefiere el parámetro rest —`function f(...args)`—, que sí da un arreglo de verdad.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(84,3,'json_2026',32,'¿Qué ocurre con la memoria de las variables locales al concluir la ejecución de su función?','Al terminar la función, sus variables locales dejan de ser alcanzables y el recolector de basura libera esa memoria cuando le toca; no hay que liberarla a mano. Hay una excepción que vale la pena tener presente desde ya, porque aparece poco después en el propio curso: si una función interna capturó esas variables —un closure—, siguen vivas después de que la función externa terminó, porque todavía queda quien las alcance. Las otras tres describen cosas que no pasan: no se quedan hasta reiniciar el navegador, no se exportan al ámbito global, y no se guardan en `localStorage`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(85,3,'json_2026',33,'Al acceder a una propiedad dinámica cuyo nombre está en una variable, ¿qué notación es obligatoria?','Cuando el nombre de la propiedad está guardado en una variable hay que usar corchetes, `objeto[variable]`, porque así se evalúa la variable y se usa su contenido como clave. Con punto, `objeto.variable`, se buscaría una propiedad llamada literalmente «variable». Las notaciones con flecha y con guion no existen en JavaScript; la de flecha es de PHP y C++.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(86,3,'json_2026',34,'¿Qué define estrictamente a un "método" en el paradigma orientado a objetos de JavaScript?','Un método no es una categoría aparte: es sencillamente una propiedad cuyo valor resulta ser una función. Por eso se puede agregar uno a un objeto ya creado con una asignación corriente, y por eso `typeof obj.metodo` responde `"function"`. Entender esto es lo que hace que después no sorprenda pasar métodos como argumentos o guardarlos en variables.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(87,3,'json_2026',35,'Si intentas consultar una propiedad que no existe dentro de un objeto literal, ¿qué evalúa JS?','Consultar una propiedad que no existe devuelve `undefined`, sin error. Eso es cómodo y a la vez peligroso: el programa sigue con un `undefined` que puede reventar más adelante, lejos de donde estuvo la causa. El `ReferenceError` de la (d) es para variables que no existen, que es otra cosa: acceder a una propiedad inexistente de un objeto que sí existe nunca lanza.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(88,3,'json_2026',36,'¿Qué función del objeto Math permite redondear un decimal hacia el entero superior más cercano?','`Math.ceil()` redondea siempre hacia arriba: `Math.ceil(4.1)` da 5. Las otras tres son reales y hacen otra cosa: `Math.floor()` redondea siempre hacia abajo, `Math.round()` al entero más cercano según el decimal, y `Math.trunc()` corta la parte decimal sin mirar. Con negativos se separan de verdad: `Math.ceil(-4.7)` da -4 y `Math.trunc(-4.7)` da -4, pero `Math.floor(-4.7)` da -5.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(89,3,'json_2026',37,'Para generar un número seudoaleatorio decimal entre 0 y casi 1, ¿qué invocación es la correcta?','`Math.random()` devuelve un decimal entre 0 incluido y 1 excluido. Nunca llega a 1, y por eso la fórmula habitual para un entero en un rango es `Math.floor(Math.random() * n)`. `Math.rand()`, `Math.rnd()` y `Math.getSeed()` no existen; la última además insinúa algo que JavaScript no ofrece: no hay forma de fijar la semilla del generador.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(90,3,'json_2026',38,'¿Qué método de la instancia String extrae una porción de texto basada en índices de inicio y fin?','`slice(inicio, fin)` devuelve el trozo entre esos índices, sin incluir el final, y no modifica la cadena original —las cadenas son inmutables—. `split()` existe pero parte la cadena en un arreglo usando un separador; `splice()` es de arreglos y además muta; `extract()` no existe. Que `slice` funcione igual en cadenas y en arreglos ayuda a recordarlo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(91,3,'json_2026',39,'Al invocar el método `String.prototype.indexOf()`, ¿qué se retorna si la subcadena no existe?','`indexOf()` devuelve la posición de la primera coincidencia y `-1` si no encuentra nada. Se eligió `-1` porque cualquier posición válida es cero o mayor, así que no se confunde con un resultado real. Justamente por eso hay que compararlo con `-1` y no usarlo como booleano: la posición `0` es un hallazgo válido y es falsy, que es el error clásico. Cuando solo interesa saber si está, `includes()` es más claro.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(92,3,'json_2026',40,'¿Cuál es la diferencia estructural entre crear un string primitivo y usar `new String()`?','`new String("hola")` construye un objeto envoltorio, mientras que `"hola"` es un valor primitivo. Se nota al comparar: `typeof` responde `"object"` en el primero y `"string"` en el segundo, y `new String("a") === "a"` es falso. En la práctica no se usa `new String()`, porque el motor envuelve el primitivo solo cuando hace falta llamar a un método.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(93,3,'json_2026',41,'¿Qué recorre cada ciclo al aplicar `for...in` frente a `for...of` sobre un arreglo?','`for...in` recorre las **claves** —en un arreglo, los índices, y además como texto— y `for...of` recorre los **valores**. Por eso sobre arreglos casi siempre se quiere `for...of`. Y hay una razón más para no usar `for...in` con arreglos: también recorre propiedades heredadas o agregadas al objeto, así que puede devolver más de lo que uno espera.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(94,3,'json_2026',42,'Al invocar `sort()` sin argumentos sobre el arreglo [10, 9, 100], ¿en qué orden queda y por qué?','Queda `[10, 100, 9]`. Sin función comparadora, `sort()` convierte cada elemento a texto y ordena alfabéticamente, y como texto `"10"` va antes que `"100"` y este antes que `"9"`, porque compara carácter a carácter. Para ordenar números de verdad hay que dárselo escrito: `arr.sort((a, b) => a - b)`. Es uno de los comportamientos más sorprendentes del lenguaje y por eso se pregunta tanto.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(95,3,'json_2026',43,'En una estructura `switch`, ¿qué consecuencia acarrea omitir la sentencia `break` en un caso?','Sin `break`, la ejecución sigue cayendo hacia los casos siguientes y los ejecuta aunque no coincidan, hasta encontrar un `break` o terminar el `switch`. Se llama fall-through y a veces se usa a propósito, agrupando varios casos que comparten el mismo cuerpo. Lo que nunca hace es lanzar error, repetirse ni volver al principio.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(96,3,'json_2026',44,'¿Cuál es la sintaxis correcta del operador condicional ternario para asignar un valor?','La forma es `condición ? valorSiVerdadero : valorSiFalso`, y devuelve un valor, por eso se puede asignar directo. La (a) mezcla `if` con el ternario, que no se combinan; la (b) usa `|`, que es un operador de bits; y la (d) usa la flecha de las funciones. Es el único operador de JavaScript que toma tres operandos, de ahí el nombre.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(97,3,'json_2026',45,'¿Qué delimitador y qué marcador exige una plantilla literal para interpolar una expresión?','Las plantillas literales van entre comillas invertidas y la expresión se interpola con `${...}`. Dentro se puede poner cualquier expresión, no solo una variable, y además el texto puede ocupar varias líneas sin escapar nada, que es la otra ventaja frente a las comillas normales. Los marcadores `#{}`, `%%` y `@{}` son de otros lenguajes: el primero es de Ruby.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(98,3,'json_2026',46,'Si a un arreglo de diez elementos se le asigna `length = 4`, ¿qué le sucede a su contenido?','`length` es de lectura y escritura, y bajarlo trunca el arreglo: los elementos desde el índice 4 en adelante se descartan y no vuelven. Es la forma más corta de vaciar un arreglo, `arr.length = 0`. Las otras tres suponen protecciones que no existen: no es de solo lectura, no reordena nada y no hay capacidad reservada que pueda desbordarse.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(99,3,'json_2026',47,'Respecto al método `push()` sobre un arreglo, ¿dónde inserta y qué valor devuelve la llamada?','`push()` agrega al final y devuelve la nueva longitud, no el elemento. Confundirlo importa cuando se encadena o se guarda el resultado. El que agrega al principio es `unshift()`, y también devuelve la longitud. Ninguno de los dos devuelve una copia: los dos modifican el arreglo original.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(100,3,'json_2026',48,'¿Cuál es la distinción sustantiva entre invocar `slice()` y aplicar `splice()` sobre un arreglo?','`slice()` devuelve un trozo nuevo y deja el original intacto; `splice()` modifica el arreglo en su sitio, quitando o insertando elementos, y devuelve los que sacó. Los nombres se parecen tanto que la confusión es habitual, y la consecuencia no es menor: uno destruye datos y el otro no. La (d) es falsa: `slice` existe en cadenas **y** en arreglos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(101,3,'json_2026',49,'Al ejecutar `parseInt("08px")`, ¿qué valor entrega el analizador y bajo qué criterio se detiene?','Devuelve el número `8`. `parseInt` lee desde el principio mientras encuentre caracteres válidos y se detiene en el primero que no lo sea, aquí la `p`, devolviendo lo leído hasta ahí. El `0` inicial no lo vuelve octal: eso ocurría en motores antiguos y el estándar lo fijó en decimal salvo que se indique la base, `parseInt("08", 10)`. Devolvería `NaN` solo si no hubiera ningún dígito al principio, como en `parseInt("px8")`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(102,3,'json_2026',50,'Si un objeto se declara con `const`, ¿qué operaciones permanecen permitidas sobre él?','`const` protege la **asignación del identificador**, no el contenido del objeto. Se pueden modificar, agregar y borrar propiedades; lo que falla es `obj = otroObjeto`. Para impedir también los cambios internos existe `Object.freeze()`, que es otra cosa y hay que pedirla. Suponer que `const` congela el objeto es uno de los malentendidos más extendidos del lenguaje.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(103,3,'js_2026',1,'En condicionales, ¿qué sucede al evaluar una expresión con coerción de tipos estricta (===)?','`===` compara valor y tipo sin convertir nada: si los tipos difieren, el resultado es falso y ahí termina. Por eso `"5" === 5` da falso mientras `"5" == 5` da verdadero. La (a) describe a `==`, que es el operador contrario; la (c) inventa un error que no ocurre —comparar tipos distintos es legal—; y la (d) describe a `||`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(104,3,'js_2026',2,'¿Qué evalúa correctamente la expresión ''typeof null'' en JavaScript por un error histórico del lenguaje?','`typeof null` responde `"object"`, y es un error conocido que viene de la primera implementación de JavaScript en 1995: internamente los valores llevaban una etiqueta de tipo y la de `null` coincidía con la de los objetos. Nunca se arregló porque hacerlo rompería código existente. Para comprobar si algo es `null` hay que compararlo directo: `valor === null`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(105,3,'js_2026',3,'¿Cuál es la precedencia al evaluar una expresión matemática compleja en código JavaScript?','Multiplicación y división se evalúan antes que suma y resta, y los paréntesis mandan sobre todo. Los operadores lógicos tienen precedencia **menor** que los aritméticos, así que la (a) está al revés; la asignación es de las últimas en evaluarse, no de las primeras; y la (d) describe una evaluación sin precedencia, que no es la de JavaScript ni la de la aritmética.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(106,3,'js_2026',4,'¿Qué método de arreglos elimina el último elemento y retorna su valor simultáneamente?','`pop()` quita el último elemento y devuelve ese elemento, así que sirve para sacar y usar en un solo paso. `shift()` hace lo mismo pero con el primero; `unshift()` agrega al principio; y `push()` agrega al final. Los cuatro modifican el arreglo original, y conviene aprenderlos por pares: `push`/`pop` al final, `unshift`/`shift` al principio.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(107,3,'js_2026',5,'¿Qué problema crítico ocurre al declarar variables iteradoras globales en ciclos anidados (for)?','Si los dos ciclos comparten la misma variable global como contador, el ciclo interior la deja en su valor final y el exterior continúa desde ahí, así que el exterior no completa sus vueltas. La salida es declarar el contador con `let` dentro de cada `for`, que le da a cada ciclo el suyo. No hay error de sintaxis ni desbordamiento: el programa corre y da un resultado equivocado, que es peor.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(108,3,'js_2026',6,'¿Cuál es el riesgo de modificar un arreglo mientras se itera linealmente sobre él (ej: borrando)?','Al borrar un elemento, los que están detrás se corren una posición hacia atrás mientras el índice del ciclo sigue avanzando, así que el que ocupó el lugar del borrado se salta sin visitarse. Las salidas habituales son recorrer de atrás hacia adelante, o construir un arreglo nuevo con `filter()` en vez de modificar el que se está recorriendo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(109,3,'js_2026',7,'¿Qué ocurre con las variables declaradas dentro de una función regular utilizando ''var''?','`var` tiene alcance de **función**: la variable existe en toda la función donde se declaró, y no fuera. Ese es su contraste con `let` y `const`, que tienen alcance de bloque y por eso desaparecen al cerrar un `if` o un `for`, lo que describe la (d). Y no se vuelve global: eso pasa al asignar sin declarar, que es otra cosa.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(110,3,'js_2026',8,'Si una función no tiene una sentencia return explícita, ¿qué valor retorna por defecto al invocarse?','Sin `return`, la función devuelve `undefined`. Es el valor por omisión y no un caso especial. Los otros tres son valores concretos que alguien tendría que haber escrito: `null` significa vacío a propósito, `false` es un booleano y `0` un número. Reconocer un `undefined` inesperado suele ser la pista de que una función no devolvía lo que se creía.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(111,3,'js_2026',9,'¿Cuál es el problema estructural causado por abusar de las variables globales en funciones?','Cualquier función puede escribir una variable global, así que dos funciones que no se conocen pueden pisarse el valor; y como todas dependen del mismo estado compartido, quedan acopladas y no se pueden mover ni probar por separado. Las otras tres describen problemas inventados: las globales no tocan la memoria de video, no bloquean el DOM y no impiden anidar funciones.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(112,3,'js_2026',10,'¿Cuál es la sintaxis correcta para acceder a un método interno de objeto mediante la notación de punto?','La notación de punto es `objeto.metodo()`: el nombre del objeto, un punto, el nombre del método y los paréntesis que lo invocan. `->` es de PHP y C++, `::` es de C++ y de la sintaxis de clases de otros lenguajes, y `objeto[metodo()]` usa corchetes, que sí existen en JavaScript pero con otro sentido: ahí se evaluaría `metodo()` y su resultado se usaría como nombre de propiedad.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(113,3,'js_2026',11,'Al llamar String.prototype.slice(1, -1) en la cadena "Prueba", ¿qué porción de texto se retorna?','Devuelve `"rueb"`. `slice(1, -1)` empieza en el índice 1, que es la `r`, y el `-1` cuenta desde el final, así que corta antes del último carácter y deja fuera la `a` final. La `P` inicial se pierde por empezar en 1 y la `a` final por el índice negativo. Poder usar índices negativos para contar desde atrás es lo que la pregunta evalúa, y es propio de `slice`: `substring` no lo admite.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
